"""
Golden tests against an independent ephemeris
---------------------------------------------
Fixtures in tests/fixtures/reference_positions.json were generated from the
Swiss Ephemeris (Moshier theory) by tools/generate_reference.py. That is a
different theory from the one this application implements, so these tests
measure real accuracy rather than confirming the implementation against itself.

Tolerances are set slightly above the errors actually measured; they exist to
catch regressions, not to assert a level of accuracy the engine does not have.
"""

# Generated by GitHub Copilot - Sep-27-2026

import json
import os
import sys
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)

from engine import ephemeris as eph
from engine.planets import JyotishChart

FIXTURE = os.path.join(ROOT, "tests", "fixtures", "reference_positions.json")

# Worst-case longitude tolerance per body, in arcseconds. These reflect the
# accuracy of the underlying theory: the Keplerian element set is the limit for
# the planets, and the truncated true-node series is the limit for Rahu/Ketu.
LONGITUDE_TOLERANCE_ARCSEC = {
    "Surya": 25.0,
    "Chandra": 20.0,
    # Tightened in V1.2. Mercury and Venus improved because the Earth's
    # heliocentric position — which every geocentric direction is measured
    # from — moved to VSOP87 along with Jupiter and Saturn.
    "Budha": 15.0,
    "Shukra": 20.0,
    # Tightened in V1.3: Mars moved to VSOP87A.
    "Mangal": 15.0,
    # Tightened in V1.2 from 450"/650": Jupiter and Saturn now use VSOP87A
    # rather than the Keplerian element set.
    "Guru": 8.0,
    "Shani": 10.0,
    # Tightened in V1.1. The true node is now derived geometrically from the
    # osculating lunar orbit rather than from a five-term correction series,
    # which cut its worst error on these cases from about 1000" to 31".
    "Rahu": 70.0,
    "Ketu": 70.0,
}

SPEED_TOLERANCE_DEG_PER_DAY = {
    "Surya": 0.005, "Chandra": 0.010, "Budha": 0.005, "Shukra": 0.005,
    "Mangal": 0.005, "Guru": 0.005, "Shani": 0.005,
}

AYANAMSHA_TOLERANCE_ARCSEC = 0.5
LAGNA_TOLERANCE_ARCSEC = 5.0
DELTA_T_TOLERANCE_SECONDS = 2.0

PLANETS = ["Surya", "Chandra", "Mangal", "Budha", "Guru", "Shukra", "Shani",
           "Rahu", "Ketu"]


def load_fixture() -> dict:
    with open(FIXTURE, "r", encoding="utf-8") as fh:
        return json.load(fh)


def arc_difference(a: float, b: float) -> float:
    """Shortest angular separation in arcseconds."""
    return abs((a - b + 180.0) % 360.0 - 180.0) * 3600.0


class ReferenceCaseTest(unittest.TestCase):
    """Compare every computed quantity against the independent reference."""

    @classmethod
    def setUpClass(cls):
        cls.data = load_fixture()
        cls.cases = cls.data["cases"]
        cls.boundaries = cls.data["boundaries"]
        cls.charts = {
            case["label"]: JyotishChart(jde=case["jd_ut"], lat=case["latitude"],
                                        lon=case["longitude"])
            for case in cls.cases
        }

    def test_fixture_covers_the_supported_range(self):
        years = sorted(int(case["utc"][:4]) for case in self.cases)
        self.assertLessEqual(years[0], 1900, "fixture must cover early dates")
        self.assertGreaterEqual(years[-1], 2040, "fixture must cover late dates")
        latitudes = [case["latitude"] for case in self.cases]
        self.assertLess(min(latitudes), 0, "needs a southern-hemisphere case")
        self.assertGreater(max(latitudes), 60, "needs a high-latitude case")

    def test_delta_t(self):
        """Tight inside the observed record, loose where both sides project."""
        for case in self.cases:
            year = int(case["utc"][:4])
            tolerance = 0.5 if year <= 2026 else 25.0
            with self.subTest(case=case["label"]):
                got = eph.delta_t_seconds(case["jd_ut"])
                self.assertAlmostEqual(got, case["delta_t_seconds"], delta=tolerance)

    def test_ayanamsha_all_systems(self):
        for case in self.cases:
            jd_tt = eph.jd_ut_to_tt(case["jd_ut"])
            for system, expected in case["ayanamsha"].items():
                with self.subTest(case=case["label"], ayanamsha=system):
                    error = abs(eph.ayanamsha(jd_tt, system) - expected) * 3600
                    self.assertLess(error, AYANAMSHA_TOLERANCE_ARCSEC)

    def test_tropical_longitudes(self):
        for case in self.cases:
            jd_tt = eph.jd_ut_to_tt(case["jd_ut"])
            for body in PLANETS:
                with self.subTest(case=case["label"], body=body):
                    got = eph.tropical_longitude(body, jd_tt, true_node=True)
                    error = arc_difference(got, case["bodies"][body]["tropical"])
                    self.assertLess(error, LONGITUDE_TOLERANCE_ARCSEC[body],
                                    f"{body} tropical error {error:.1f}\"")

    def test_sidereal_longitudes(self):
        for case in self.cases:
            chart = self.charts[case["label"]]
            for body in PLANETS:
                with self.subTest(case=case["label"], body=body):
                    error = arc_difference(chart.planets[body].longitude,
                                           case["bodies"][body]["sidereal"])
                    self.assertLess(error, LONGITUDE_TOLERANCE_ARCSEC[body])

    def test_mean_node_is_more_accurate_than_true_node(self):
        for case in self.cases:
            jd_tt = eph.jd_ut_to_tt(case["jd_ut"])
            with self.subTest(case=case["label"]):
                error = arc_difference(eph.lunar_node(jd_tt, true_node=False),
                                       case["bodies"]["Rahu_mean"]["tropical"])
                self.assertLess(error, 25.0, "mean node should be near-exact")

    def test_sign_nakshatra_and_pada(self):
        for case in self.cases:
            chart = self.charts[case["label"]]
            for body in PLANETS:
                expected = case["bodies"][body]
                position = chart.planets[body]
                with self.subTest(case=case["label"], body=body):
                    self.assertEqual(position.rashi, expected["sign"])
                    self.assertEqual(position.rashi_index, expected["sign_index"])
                    self.assertEqual(position.nakshatra, expected["nakshatra"])
                    self.assertEqual(position.pada, expected["pada"])
                    self.assertAlmostEqual(position.degree_in_rashi,
                                           expected["degree_in_sign"],
                                           delta=LONGITUDE_TOLERANCE_ARCSEC[body] / 3600)

    def test_speed_and_retrogression(self):
        for case in self.cases:
            chart = self.charts[case["label"]]
            for body, tolerance in SPEED_TOLERANCE_DEG_PER_DAY.items():
                expected = case["bodies"][body]
                with self.subTest(case=case["label"], body=body):
                    self.assertAlmostEqual(chart.planets[body].speed,
                                           expected["speed"], delta=tolerance)
                    self.assertEqual(chart.planets[body].is_retrograde,
                                     expected["retrograde"],
                                     f"{body} retrograde flag")

    def test_lagna_and_midheaven(self):
        for case in self.cases:
            chart = self.charts[case["label"]]
            with self.subTest(case=case["label"]):
                error = arc_difference(chart.lagna.longitude,
                                       case["lagna"]["sidereal"])
                self.assertLess(error, LAGNA_TOLERANCE_ARCSEC)
                self.assertEqual(chart.lagna.rashi, case["lagna"]["sign"])
                self.assertEqual(chart.lagna.nakshatra, case["lagna"]["nakshatra"])
                self.assertEqual(chart.lagna.pada, case["lagna"]["pada"])
                self.assertLess(arc_difference(chart.midheaven,
                                               case["midheaven"]["sidereal"]),
                                LAGNA_TOLERANCE_ARCSEC)


class BoundaryTest(unittest.TestCase):
    """
    Each case sits just outside a sign, nakshatra or pada boundary, by more
    than the engine's own error for that body. Landing on the correct side is
    therefore a genuine requirement, not luck.
    """

    @classmethod
    def setUpClass(cls):
        cls.boundaries = load_fixture()["boundaries"]

    def test_boundary_cases_exist_for_each_kind(self):
        kinds = {case["kind"] for case in self.boundaries}
        self.assertEqual(kinds, {"sign", "nakshatra", "pada"})

    def test_classification_on_the_correct_side_of_the_boundary(self):
        for case in self.boundaries:
            jd_tt = eph.jd_ut_to_tt(case["jd_ut"])
            ayanamsha = eph.ayanamsha(jd_tt, "lahiri")
            sidereal = (eph.tropical_longitude(case["body"], jd_tt) - ayanamsha) % 360
            position = JyotishChart._position_from_sidereal(case["body"], sidereal, 1.0)
            with self.subTest(case=case["label"]):
                self.assertEqual(position.rashi, case["sign"],
                                 f"{case['label']}: sign on wrong side of boundary")
                self.assertEqual(position.nakshatra, case["nakshatra"],
                                 f"{case['label']}: wrong nakshatra")
                self.assertEqual(position.pada, case["pada"],
                                 f"{case['label']}: wrong pada")


if __name__ == "__main__":
    unittest.main(verbosity=2)
